#include "cinderwatch/policy/policy.h"
namespace cinderwatch::policy{using namespace core;static void add(Policy&p,std::string s,std::string k,std::vector<std::string>v,size_t l){p.items.push_back({lower(trim(s)),lower(trim(k)),std::move(v),{p.source,l,1,0}});}Policy parse_ini(const std::string&t,const std::string&s){Policy p;p.source=s;std::string sec="default";size_t n=0;for(auto&l:lines(t)){n++;auto x=trim(l);if(x.empty()||x[0]=='#'||x[0]==';')continue;if(x.front()=='['&&x.back()==']'){sec=x.substr(1,x.size()-2);continue;}auto pos=x.find('=');if(pos==std::string::npos)pos=x.find(':');if(pos==std::string::npos){p.diagnostics.push_back({Severity::Low,"policy.ini","line has no separator",{s,n,1,0}});continue;}auto vals=split(x.substr(pos+1),',');for(auto&v:vals)v=trim(v);add(p,sec,x.substr(0,pos),vals,n);}return p;}Policy parse_csv(const std::string&t,const std::string&s){Policy p;p.source=s;size_t n=0;for(auto&l:lines(t)){n++;auto c=split(l,',');if(c.size()<3)continue;std::vector<std::string>v;for(size_t i=2;i<c.size();++i)v.push_back(trim(c[i]));add(p,c[0],c[1],v,n);}return p;}Policy parse_json(const std::string&t,const std::string&s){Policy p;p.source=s;std::vector<std::string>str;std::string c;bool q=false;for(char x:t){if(x=='"'){if(q){str.push_back(c);c.clear();q=false;}else q=true;}else if(q)c.push_back(x);}for(size_t i=0;i+1<str.size();i+=2)add(p,"json",str[i],{str[i+1]},1);return p;}Policy parse_auto(const std::string&t,const std::string&s){auto x=trim(t);if(!x.empty()&&x[0]=='{')return parse_json(t,s);if(x.find(',')!=std::string::npos&&x.find('=')==std::string::npos)return parse_csv(t,s);return parse_ini(t,s);}Policy parse_file(const std::string&p){auto t=read_text(p);if(!t){Policy q;q.source=p;q.diagnostics.push_back({Severity::High,"policy.file",t.st.msg,{p,1,1,0}});return q;}return parse_auto(t.value(),p);}static bool key(const Item&i,const std::string&k){return i.key==k||i.key==k+"s";}Report validate(const Policy&p){Report r;r.subject="Policy validation";r.diagnostics=p.diagnostics;bool an=false,bn=false,post=false;for(auto&i:p.items)for(auto&v:i.values){if(key(i,"allowed_network")||key(i,"blocked_network")){auto c=parse_cidr(v);if(!c)r.findings.push_back({Severity::Medium,"policy","Invalid network",i.key+" contains invalid CIDR",i.loc,{v}});else{if(key(i,"allowed_network"))an=true;else bn=true;if(c.value().prefix==0&&key(i,"allowed_network"))r.findings.push_back({Severity::High,"policy","Broad allowed network","Allowed network covers all IPv4 space",i.loc,{v}});}}else if(key(i,"approved_dns_domain")||key(i,"forbidden_domain")){if(!domain_like(v))r.findings.push_back({Severity::Medium,"policy","Invalid domain",v,i.loc,{}});}else if(key(i,"allowed_port")||key(i,"denied_port")){auto pr=parse_port_range(v);if(!pr)r.findings.push_back({Severity::Medium,"policy","Invalid port range",v,i.loc,{}});}else if(i.key=="required_firewall_posture"){post=true;if(lower(v).find("deny")==std::string::npos)r.findings.push_back({Severity::Medium,"policy","Weak firewall posture","Posture does not mention deny behavior",i.loc,{v}});}}if(!an)r.findings.push_back({Severity::Low,"policy","No allowed networks","Policy does not define allowed networks"});if(!bn)r.findings.push_back({Severity::Low,"policy","No blocked networks","Policy does not define blocked networks"});if(!post)r.findings.push_back({Severity::Medium,"policy","No firewall posture","Policy does not define required firewall posture"});return r;}Report audit_bundle(const std::string&d){Report out;out.subject="Bundle audit";std::error_code ec;for(auto&e:std::filesystem::directory_iterator(d,ec)){if(!e.is_regular_file())continue;auto p=e.path().string();auto ext=lower(e.path().extension().string());auto t=read_text(p);if(!t)continue;if(ext==".rules"){auto ids=rules::parse_ids_rules(t.value());auto ir=rules::validate_ids(ids);out.findings.insert(out.findings.end(),ir.findings.begin(),ir.findings.end());auto fw=rules::parse_firewall(t.value());auto fr=rules::validate_firewall(fw);out.findings.insert(out.findings.end(),fr.findings.begin(),fr.findings.end());}else if(ext==".ini"||ext==".json"||ext==".csv"||ext==".policy"){auto po=parse_auto(t.value(),p);auto pr=validate(po);out.findings.insert(out.findings.end(),pr.findings.begin(),pr.findings.end());}}if(ec)out.diagnostics.push_back({Severity::High,"bundle.dir",ec.message(),{d,1,1,0}});return out;}std::string text(const Policy&p,const Report&r){std::ostringstream o;o<<"Policy items parsed: "<<p.items.size()<<"\n"<<report_text(r);return o.str();}std::string json(const Policy&p,const Report&r){return std::string("{\"items\":")+std::to_string(p.items.size())+",\"report\":"+report_json(r)+"}";}}
